import{z as o,x as n,o as e,c as p,q as r,j as l,D as a,d as B,s,S as i,b as A}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"胶的热流与回流","description":"","frontmatter":{"title":"胶的热流与回流","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/resist-reflow.md","filePath":"litho/resist-reflow.md","lastUpdated":1791413859000}'),D={name:"litho/resist-reflow.md"};function d(h,E,T,m,C,_){const t=n("Mermaid");return e(),p("div",null,[E[2]||(E[2]=r('<h1 id="胶的热流与回流" tabindex="-1">胶的热流与回流 <a class="header-anchor" href="#胶的热流与回流" aria-label="Permalink to &quot;胶的热流与回流&quot;">​</a></h1><div class="epigraph"><p>显影已经切出浮雕之后，再加热可以把棱角流圆、把孔收小：这是黏滞流动，不是第二次 PEB 催化。</p><footer>—— 据产线回流（resist reflow）工艺通称；聚合物流动见 Tg 以上的黏度语言</footer></div><p><a href="/litho/dose-focus-coupling">上一课</a>把曝光–显影窗写到平均 CD。缺口是显影后还可以再动一次几何：热回流。接触孔缩小、侧壁修圆、有时故意把线端变钝，都走这条路。本课钉回流。流动能不能发生，取决于玻璃化温度与自由体积，留给<a href="/litho/tg-free-volume">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>PEB 发生在显影前，对象是酸与保护基。回流发生在显影后（有时在硬烘），对象是已经成形的聚合物浮雕。温度够高、时间够长，表面张力驱动材料从高曲率处流向低曲率处：孔的顶角变圆、孔径缩小，线的肩变塌。光学剂量没有再写一次，CD 却变了——故障隔离时若仍去拧扫描机，会拧错执行器。</p><p>缺口不是再讲 Arrhenius 催化，而是：这是流体力学尺度的质量守恒，潜像化学已经冻结（除非残留溶剂还在塑化）。把回流写成「又一次 PEB」，会把酸核和黏度混成一个烘箱配方。</p><p><span class="marginnote">常见误区：显影后孔变小，第一反应是去拧扫描机剂量。若这层做了回流，孔径由热板温度与时间共同决定，剂量不动 CD 也会漂——故障隔离先问「显影之后有没有热过程」，再动曝光执行器。</span></p><h3 id="故意回流与事故回流" tabindex="-1">故意回流与事故回流 <a class="header-anchor" href="#故意回流与事故回流" aria-label="Permalink to &quot;故意回流与事故回流&quot;">​</a></h3><p>孔层有时故意回流来买更小的 ADI 孔。线层通常禁止：肩一塌，CD 与侧壁角一起漂，刻蚀转移失控。同一条热板程序，对孔是工艺，对线是缺陷。规格必须按图形类别写。</p><p><span class="marginnote">回流改变的是显影后体积分配，不增加衬度。NILS 不够的孔回流之后可以变圆变小，但随机缺孔不会被「流没」；材料从四周挤入，LCDU 可能更差。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>旋钮：温度相对 \\(T_g\\) 的距离、时间、升温斜率、胶厚与图形密度。表征：回流前后 CD、侧壁、孔椭圆度、膜厚。密集图形之间的材料竞争会造成邻近相关的 CD 漂移，看起来像 OPE——要用「只回流、不改曝光」的对照矩阵拆开。</p><p><span class="marginnote">数字实例：黏度随温度近似指数变化，\\(T_g\\) 附近差 5-10 °C，流动量就可能差几倍。这就是回流窗口按「热板设定 ± 1 °C」这类公差管理、而不像普通硬烘那样宽松的原因。</span></p><p>仿真：连续介质黏流 + 表面张力，输入黏度 \\(\\eta(T)\\)。不需要再解 Dill 方程。OPC 若在回流层上做，必须把回流核标定进紧凑模型，否则平均边会对，孔阵列的密度效应会撒谎。</p>',14)),(e(),l(i,null,{default:a(()=>[s(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20ADI%5B%22%E6%98%BE%E5%BD%B1%E5%90%8E%E6%B5%AE%E9%9B%95%22%5D%20--%3E%20HEAT%5B%22T%20%3E%20Tg%20%E5%9B%9E%E6%B5%81%22%5D%0A%20%20HEAT%20--%3E%20ROUND%5B%22%E6%9B%B2%E7%8E%87%E9%A9%B1%E5%8A%A8%E6%B5%81%E5%8A%A8%22%5D%0A%20%20ROUND%20--%3E%20HOLE%5B%22%E5%AD%94%E5%BE%84%E7%BC%A9%E5%B0%8F%20%2F%20%E8%82%A9%E5%A1%8C%22%5D%0A%20%20TG%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9ATg%20%E4%B8%8E%E8%87%AA%E7%94%B1%E4%BD%93%E7%A7%AF%22%5D%20--%3E%20HEAT%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[B("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,"聚合物在 \\(T_g\\) 以上进入高弹/黏流区，有效黏度下降若干数量级。表面能最小化让凸肩塌、凹孔收。厚胶、大曲率（小孔、尖线端）流动更快。残留溶剂当增塑剂，把有效 \\(T_g\\) 压低，同一热板设定下流得更狠——下一课与 PAB 课会接这句话。",-1)),(e(),l(i,null,{default:a(()=>[s(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20HEAT%5B%22%E5%90%8C%E4%B8%80%E7%83%AD%E6%9D%BF%3A%20T%20%E5%A4%A7%E4%BA%8E%20Tg%22%5D%20--%3E%20HOLE%5B%22%E5%AD%94%3A%20%E5%87%B8%E9%A1%B6%E8%A7%92%E5%8F%98%E5%9C%86%22%5D%0A%20%20HEAT%20--%3E%20LINE%5B%22%E7%BA%BF%3A%20%E8%82%A9%E9%83%A8%E5%A1%8C%E9%99%B7%22%5D%0A%20%20HOLE%20--%3E%20SHRINK%5B%22%E5%AD%94%E5%BE%84%E7%BC%A9%E5%B0%8F%22%5D%0A%20%20SHRINK%20--%3E%20GOOD%5B%22%E5%AD%94%E5%B1%82%3A%20%E4%B9%B0%E5%88%B0%E6%9B%B4%E5%B0%8F%20ADI%20%E5%AD%94%22%5D%0A%20%20LINE%20--%3E%20SWA%5B%22CD%20%E4%B8%8E%E4%BE%A7%E5%A3%81%E8%A7%92%E4%B8%80%E8%B5%B7%E6%BC%82%22%5D%0A%20%20SWA%20--%3E%20BAD%5B%22%E7%BA%BF%E5%B1%82%3A%20%E5%88%BB%E8%9A%80%E8%BD%AC%E7%A7%BB%E5%A4%B1%E6%8E%A7%22%5D%0A%20%20SOLV%5B%22%E6%AE%8B%E7%95%99%E6%BA%B6%E5%89%82%E5%8E%8B%E4%BD%8E%E6%9C%89%E6%95%88%20Tg%22%5D%20--%3E%20WORSE%5B%22%E5%90%8C%E4%B8%80%E8%AE%BE%E5%AE%9A%E6%B5%81%E5%BE%97%E6%9B%B4%E7%8B%A0%22%5D%0A%20%20ACID%5B%22%E6%98%BE%E5%BD%B1%E5%90%8E%E6%AE%8B%E9%85%B8%E7%BB%A7%E7%BB%AD%E5%82%AC%E5%8C%96%22%5D%20--%3E%20SHRINKV%5B%22%E9%A2%9D%E5%A4%96%E4%BD%93%E7%A7%AF%E6%94%B6%E7%BC%A9%2C%20%E9%9D%9E%E7%BA%AF%E6%B5%81%E5%8A%A8%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p>酸催化在回流温度也可能继续，若显影后仍有活酸。那是污染项：正胶残留酸会让回流伴随额外体积收缩。工艺上要声明是「纯流动」还是「流动 + 残余反应」。</p><p><span class="marginnote">193 nm CAR 的 \\(T_g\\) 常靠近 PEB 设定，回流窗口窄。i 线 novolac 硬烘回流是更老的工作点，不要把两套温度表复印。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写某供应商的回流食谱。不把回流当 RET：它改的是已印图形的三维，救不了零级偏置。下一课给出 \\(T_g\\) 与自由体积，使「为什么这条胶流、那条不流」有聚合物语言。老化与保质会改残留溶剂与 \\(T_g\\)，再下一课。</p><p><span class="marginnote">直觉类比：回流像把刻过字的蜡烛轻微加热——表面张力把尖角棱边抹圆，蜡从凸处流向凹处。它不会把刻痕填平回原样，只会让轮廓变钝变圆，方向由曲率决定，这就是「孔收小、肩塌下」的同一只手。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>回流是显影后的黏滞流动，不是 PEB 催化的别名。</li><li>孔可故意缩小；线肩塌通常是事故。</li><li>邻近密度会进入回流 CD，对照实验要关掉曝光变量。</li><li>残留溶剂降低有效 \\(T_g\\)，同一热板结果不同。</li><li>出处：产线 resist reflow 通称；聚合物 \\(T_g\\) 以上流动；Mack / Levinson 工艺叙述。</li></ul>',7))])}const u=o(D,[["render",d]]);export{c as __pageData,u as default};
